#: What `think=False` asks a hosted model for. A name, not a literal, so a deployment whose
#: provider spells the lowest reasoning effort differently can say so.
NO_THINK_EFFORT = 'minimal'
dflt_remote = 'gpt-5.1'      #: model for a `RemoteChat` with none named
DFLT_MAX_TOKENS = 16_000   #: output cap for a model fastllm has no maximum for; a known model gets its own
#: Vendors whose transport answers a streamed request and refuses every other one.
STREAM_ONLY = {'codex'}
#: Hosts whose chat-completions route refuses `max_tokens` from a reasoning model and takes `max_completion_tokens` from every model.
MAX_COMPLETION_HOSTS = ('.azure.com', '.azure.us', '.azure.cn')
#: The level each fastllm api takes for an effort level it lacks.
EFFORT_MAP = {'openai': {'max': 'xhigh'}, 'openai_chat': {'max': 'xhigh'}, 'gemini': {'xhigh': 'high', 'max': 'high'}}

#: The fastllm functions that decode a model's tool-call arguments. A `JSONDecodeError` from anywhere else is not the model's.
ARG_SITES = ('get_merged', 'norm_tool_calls', 'norm_tool_call', 'flush_tools', 'collate_raw')
CUT_CAP_MULT = 4   #: how many times its output cap the step after a cut-off tool call gets

def args_error(e):
    "Whether the `JSONDecodeError` `e` came from fastllm decoding a model's tool-call arguments."
    tb, site = e.__traceback__, None
    while tb:
        if tb.tb_frame.f_globals.get('__name__', '').startswith('fastllm'): site = tb.tb_frame.f_code.co_name
        tb = tb.tb_next
    return site in ARG_SITES

def cut_args(e):
    "Whether the JSON in `e` ended early, as arguments cut off at the output cap do, rather than being malformed."
    return e.msg.startswith('Unterminated') or e.pos >= len(e.doc.rstrip())

def effort_refused(e):
    "Whether `e` is a provider's 400 that names the reasoning effort (`effort`, `reasoning_effort`, `reasoning.effort`)."
    return getattr(e, 'status_code', None) == 400 and 'effort' in str(e).lower()

class RemoteChat(RishiToolLoop, Chat):
    "A `Chat` that sends each turn to a hosted model API through fastllm."
    _runtime = 'remote'
    #: what this transport calls each portable option
    _opt_map = {'ctx': 'ctx_limit', 'temp': 'temperature', 'effort': 'reasoning_effort',
                'max_output_tokens': 'max_tokens'}
    _opt_skip = ('top_k', 'top_p', 'seed', 'think')   # no hosted API takes these
    mk_content, mk_msg, mk_msgs = staticmethod(mk_content), staticmethod(mk_msg), staticmethod(mk_msgs)

    @staticmethod
    def fmt2hist(msgs):
        "fastllm `Msg`s (or canonical dicts) -> canonical history dicts."
        out = []
        for m in listify(msgs): out += to_hist(m) if isinstance(m, Msg) else [mk_msg(m)]
        return out

    @staticmethod
    def hist2fmt(msgs):
        "Canonical history dicts -> fastllm `Msg`s, media carried through rather than stripped."
        return [to_msg(m) for m in listify(msgs) if m.get('role') != 'system']

    def __init__(self, model=None, *, runtime=None, model_path=None, opts=None,
                 vendor_name=None,   # override the vendor fastllm infers from the model id
                 api_name=None,      # override the api name fastllm infers
                 tool_choice=None,   # force a particular tool, or 'required'
                 retries=2,
                 comp_kw=None,       # passed to `acomplete` verbatim
                 **kw):              # portable options; see `urai.ChatOpts`
        o = ChatOpts.create(opts, **kw)
        self.model_id = split_runtime(model)[1] or dflt_remote
        self.tool_mode = o.tool_mode or 'native'
        self.api_key, self.base_url = o.key, o.base_url or None
        self.reasoning_effort, self.temp = o.effort or None, o.temp
        self.dropped_effort = None   # why the provider refused the effort; while set, none is sent
        store_attr('vendor_name,api_name,tool_choice,retries', self)
        self.max_output_tokens = o.max_output_tokens or self._model_max() or DFLT_MAX_TOKENS
        self.ctx_limit = o.ctx or None
        self.comp_kw, self._ctx_tokens, self._boost = comp_kw or {}, 0, None
        self._set_tools(o.tools)
        self._setup(model, o)

    @property
    def token_count(self):
        "Tokens the last turn reported. Hosted APIs have no live context read-out."
        return self._ctx_tokens

    def _kw(self, stream=False, **turn):
        "Keyword arguments for `acomplete`, with this turn's own generation options applied."
        t = self.map_opts(turn)
        kw = dict(stream=stream, api_key=self.api_key, base_url=self.base_url, retries=self.retries,
                  vendor_name=self.vendor_name, api_name=self.api_name,
                  max_tokens=t.pop('max_tokens', None) or self.max_output_tokens)
        tags = self._tags(t)
        sp = tag_tools_sp(self.toolspecs, self.sp) if tags else self.sp
        if sp: kw['system'] = sp
        # in tag mode the schemas already went out in the system prompt, and sending them on the
        # wire as well is the one thing the transport cannot do
        if self.toolspecs and not tags: kw['tools'] = self.toolspecs
        if self.tool_choice is not None and not tags: kw['tool_choice'] = self.tool_choice
        if (eff := t.pop('reasoning_effort', self.reasoning_effort)) is not None and not self.dropped_effort:
            kw['reasoning_effort'] = EFFORT_MAP.get(self._api, {}).get(eff, eff) if isinstance(eff, str) else eff
        if (tmp := t.pop('temperature', self.temp)) is not None: kw['temperature'] = tmp
        t.pop('ctx_limit', None)                       # a window is not a completion argument
        out = {**kw, **self.comp_kw, **t}
        if self._max_completion and (mt := out.pop('max_tokens', None)): out['xtra_body'] = {'max_completion_tokens': mt, **(out.get('xtra_body') or {})}
        return out

    def _tags(self, t):
        "Whether this turn's tools travel as tags: its own `tool_mode`, else the chat's. `t` is `map_opts` output, and loses the key."
        return t.pop('tool_mode', self.tool_mode) == 'tags'

    @property
    def _api(self):
        "The fastllm api this chat's requests go to."
        v = self.vendor_name or split_vendor(self.model_id)[0]
        return (self.api_name or (vendor_mapping[v][0] if v in vendor_mapping else None)
                or ('openai_chat' if self.base_url and self.api_key else infer_api_name(self.model_id)))

    def _drop_effort(self, e, turn):
        "Whether `e` refused the effort this turn sent; if so `dropped_effort` says so, and the call goes once more without one."
        eff = self._kw(**turn).get('reasoning_effort')
        if eff is None or not effort_refused(e): return False
        self.dropped_effort = f'{self.model_id} refused reasoning effort {eff!r} and ran at its default: {e}'
        return True

    @property
    def _max_completion(self):
        "Whether the reply cap goes out as `max_completion_tokens`: chat completions on a host in `MAX_COMPLETION_HOSTS`."
        return self.api_name == 'openai_chat' and (urlparse(self.base_url or '').hostname or '').endswith(MAX_COMPLETION_HOSTS)

    @property
    def _wire_model(self):
        "The id `acomplete` gets: Gemini's routes need `models/`, which fastllm puts in the URL as given."
        if self._api != 'gemini': return self.model_id
        v, m = split_vendor(self.model_id)
        if '/' not in m: m = f'models/{m}'
        # `acomplete` strips the vendor only when nothing else names the route
        strips = not (self.vendor_name or self.api_name or (self.base_url and self.api_key))
        return f'{v}/{m}' if v and strips else m

    async def _acomplete(self, msgs, stream=False, **turn):
        "One `acomplete` call for `msgs` (canonical history dicts)."
        return await acomplete(self.hist2fmt(msgs), self._wire_model, **self._kw(stream, **turn))

    @property
    def _stream_only(self):
        "Whether this model's vendor will not answer a request that is not streamed."
        return (self.vendor_name or split_vendor(self.model_id)[0]) in STREAM_ONLY

    async def _collect(self, msgs, **kw):
        "One `Completion`, gathered from a stream."
        agen = await acomplete(msgs, self._wire_model, **{**kw, 'stream': True})
        comp = None
        async for part in agen:
            if isinstance(part, Completion): comp = part
        if comp is None: raise RuntimeError('stream ended without a final Completion')
        return comp

    async def _one(self, msgs, **kw):
        "One `Completion`, streamed and gathered where the vendor takes nothing else."
        if self._stream_only: return await self._collect(msgs, **kw)
        return await acomplete(msgs, self._wire_model, **kw)

    def _boosted(self, kw):
        "This step's options, with the raised output cap a cut-off tool call left for it."
        if not (b := self._boost): return kw
        self._boost = None
        return {**kw, 'max_output_tokens': b}

    def _cap(self, kw):
        "The output cap a step with options `kw` runs under."
        return self.map_opts(kw).get('max_tokens') or self.max_output_tokens

    def _model_max(self):
        "The most output fastllm says this model can write, or None."
        try: return get_model_info(self.model_id, self.vendor_name).get('max_output_tokens')
        except Exception: return None

    def _cut(self, cap, lead=None):
        "Why a reply cut off at `cap` was lost, raising the next step's cap when the model allows more."
        b, lead = min(cap * CUT_CAP_MULT, self._model_max() or cap * CUT_CAP_MULT), lead or f"{self.model_id}'s tool call was cut off"
        if b > cap: self._boost = b
        return (f"{lead} at its {cap}-token output limit; "
                + ('raise max_output_tokens, or ask for smaller steps' if b > cap else 'ask for smaller steps'))

    def _read(self, res, kw):
        "`res`, with why a reply cut off at the output cap was lost, for `_fix_step`: a call cut short, or nothing but thinking."
        if not res.get('truncated'): return res
        tcs = res.get('tool_calls') or []
        if any(tc.get('unread') for tc in tcs): res['lost'] = self._cut(self._cap(kw))
        elif not tcs and not resp_text(res).strip():
            why = self._cut(self._cap(kw), f'{self.model_id} was still thinking when its reply was cut off')
            res.pop('channels', None)   # a partial, unsigned thought would be refused when sent back
            res.update(content=f'[{why}]', tool_parse_failed=True, lost=why,
                       reparse='That reply reached the output limit while still thinking, before any answer or tool call. '
                               'Answer again, thinking less or taking a smaller step.')
        return res

    def _lost(self, e, kw, text=''):
        "The `Resp` for a step whose tool call fastllm could not decode, which `_fix_step` asks for again. Any other `JSONDecodeError` is raised."
        if not args_error(e): raise e
        if cut_args(e): why, more = self._cut(self._cap(kw)), {'truncated': True}
        else:
            why = f"{self.model_id}'s tool call arguments were not valid JSON ({e.msg} at char {e.pos})"
            more = {'reparse': f'That reply held a tool call whose arguments were not valid JSON ({e.msg} at char {e.pos}), '
                               'so it was not run. Send the call again with its arguments as one JSON object.'}
        return Resp({'role': 'assistant', 'content': text or f'[{why}]', 'tool_parse_failed': True, 'lost': why, **more})

    def _model_step(self, **kw):
        "One completion, normalized to a `Resp`, sent once more without an effort the provider refused. The wire call `ToolLoopMixin` drives."
        kw = self._boosted(kw)
        def step():
            try: return self._read(norm_completion(run_coro(self._one(self.hist2fmt(self.hist), **self._kw(**kw)))), kw)
            except json.JSONDecodeError as e: return self._lost(e, kw)
        try: return step()
        except Exception as e:
            if not self._drop_effort(e, kw): raise
        return step()

    def _stream_step(self, **kw):
        "Stream one completion, yielding chunk dicts and leaving the merged `Resp` on `self._step_res`."
        kw = self._boosted(kw)
        async def _agen():
            for again in (False, True):
                n = 0
                try:
                    async for o in await self._acomplete(self.hist, True, **kw):
                        n += isinstance(o, (Part, Completion)); yield o
                    return
                except Exception as e:
                    if n or again or not self._drop_effort(e, kw): raise
        comp, split, said = None, StreamSplit() if self._tags(self.map_opts(kw)) else None, []
        try:
            for o in sync_iter(_agen, stop=self._cancel):
                if isinstance(o, Completion): comp = o
                elif not isinstance(o, Part): continue          # a `Status` marker, not model content
                elif o.type == PartType.tool_use:
                    yield {'content': [{'type': 'tool_call', 'name': o.name or '',
                                        'arguments': o.arguments or {}}]}
                elif o.type == PartType.thinking: yield {'channels': {'thought': o.text or ''}}
                elif o.type in (PartType.text, PartType.refusal) and (t := o.text):
                    said.append(t)
                    # in tag mode the calls arrive as text, so split it on the way past: otherwise the
                    # `<tool_call>` block renders as prose before the final `Resp` turns it into a call
                    yield from (split.feed(t) if split else [{'content': [{'type': 'text', 'text': t}]}])
        except json.JSONDecodeError as e:
            self._step_res = self._lost(e, kw, ''.join(said)); return
        if split is not None: yield from split.finish()
        if comp is None: raise RuntimeError('stream ended without a final Completion')
        self._step_res = self._read(norm_completion(comp), kw)

    oneshot_stream_ok = oneshot_max_tokens_ok = True   # a deadline is refused: nothing here can cut a request short

    def _oneshot_args(self, prompt, sp, max_tokens):
        "The messages and `acomplete` options of a stateless call with no history and no tools."
        return ([to_msg({'role': 'user', 'content': prompt})],
                {**self._kw(max_output_tokens=max_tokens), 'system': sp or None, 'tools': None, 'tool_choice': None})

    async def _until_cancelled(self, awaitable, began, ait=None, opens=False):
        "The result of `awaitable`. When `cancel()` comes first, its task is cancelled, the async iterator `ait` is closed, and `OneShotCancelled` is raised. With `opens`, `awaitable` returns a stream, and one that it returns despite the cancel is closed too, within the one `CLOSE_WAIT`."
        task = asyncio.ensure_future(awaitable)
        try: done = await read_or_cancel(task, self._cancel)
        except BaseException: task.cancel(); raise
        if done: return task.result()
        t0 = time.monotonic()
        stopped = await shut_stream(ait, task)
        if opens and stopped and not task.cancelled(): stopped = await shut_stream(task.result(), wait=max(0, CLOSE_WAIT - (time.monotonic() - t0)))
        raise OneShotCancelled(time.monotonic() - began, stopped)

    def _oneshot(self, prompt, sp='', think=None, max_tokens=None):
        "Stateless completion text, with no history and no tools. `think=False` asks for `NO_THINK_EFFORT`. `cancel()` ends it with `OneShotCancelled`."
        msgs, kw = self._oneshot_args(prompt, sp, max_tokens)
        self._cancel.clear()   # a `cancel()` that ended an earlier call must not end this one
        self.oneshot_use, began = usage_stats(None), time.monotonic()
        def send(k):
            r = norm_completion(run_coro(self._until_cancelled(self._collect(msgs, **k), began)))
            self.oneshot_use = usage_stats(r.get('usage'))
            return resp_text(r)
        if think is not False: return send(kw)
        try: return send({**kw, 'reasoning_effort': NO_THINK_EFFORT})
        except Exception as e:
            if not effort_refused(e): raise
            return send(kw)   # a provider that spells the effort differently

    async def _astream(self, msgs, kw, began):
        "The parts and the final `Completion` of one streamed request. `cancel()` ends it with `OneShotCancelled`. Leaving early closes the provider's stream, and a close that does not finish within `CLOSE_WAIT` raises `OneShotCancelled(stopped=False)`."
        agen = await self._until_cancelled(acomplete(msgs, self._wire_model, **{**kw, 'stream': True}), began, opens=True)
        try:
            while True:
                try: o = await self._until_cancelled(agen.__anext__(), began, agen)
                except StopAsyncIteration: break
                yield o
        except OneShotCancelled: raise   # `_until_cancelled` has closed the stream
        except GeneratorExit:
            if not await shut_stream(agen): raise OneShotCancelled(time.monotonic() - began, False)
            raise
        except BaseException:
            await shut_stream(agen); raise
        if not await shut_stream(agen): raise OneShotCancelled(time.monotonic() - began, False)

    def _oneshot_chunks(self, msgs, kw, think):
        "Text chunks of one streamed request. `think=False` sends `NO_THINK_EFFORT` and, when the provider refuses it before any text, sends again without. `oneshot_use` is set from the final `Completion`."
        tries, began = [{**kw, 'reasoning_effort': NO_THINK_EFFORT}, kw] if think is False else [kw], time.monotonic()
        for i, k in enumerate(tries):
            n, comp = 0, None
            try:
                with closing(sync_iter(lambda: self._astream(msgs, k, began))) as it:
                    for o in it:
                        if isinstance(o, Completion): comp = o
                        elif isinstance(o, Part) and o.type == PartType.text and o.text: n += 1; yield o.text
            except Exception as e:
                if n or i == len(tries) - 1 or not effort_refused(e): raise
                continue
            break
        if comp is None: raise RuntimeError('stream ended without a final Completion')
        self.oneshot_use = usage_stats(norm_completion(comp).get('usage'))

    def oneshot_stream(self, prompt, sp='', think=None, max_tokens=None, deadline=None):
        "Yield the text of one reply to `prompt` as the provider sends it, without tools or history. Closing the iterator closes the provider's stream. `cancel()` ends it with `OneShotCancelled`, also while it waits for a chunk. A `deadline` is refused with `ValueError` before any request is made, since the backend cannot cut a request short."
        if deadline is not None: raise ValueError(f'{type(self).__name__} cannot bound a call with a deadline; pass deadline=None')
        self._cancel.clear()
        self.oneshot_use = usage_stats(None)
        return self._oneshot_chunks(*self._oneshot_args(prompt, sp, max_tokens), think)

    def _structured_call(self, prompt, schema, sp):
        "Force the tool call for `schema` and return its arguments, falling back to JSON found in prose."
        spec = mk_toolspec(schema)
        name = spec['function']['name']
        msgs, kw = [to_msg({'role': 'user', 'content': prompt})], {'system': sp or None, 'tools': [spec], 'tool_choice': name}
        try: comp = run_coro(self._one(msgs, **{**self._kw(), **kw}))
        except json.JSONDecodeError as e:   # once more, at a raised cap when the call was cut off
            why = self._lost(e, {})['lost']
            try: comp = run_coro(self._one(msgs, **{**self._kw(**self._boosted({})), **kw}))
            except json.JSONDecodeError as e2:
                if not args_error(e2): raise
                raise ToolCallError(f'{why}, and again when asked once more') from e2
        r = norm_completion(comp)
        if tcs := r.get('tool_calls'): return tcs[0].arguments
        txt = resp_text(r)
        try: return json.loads(extract_fence(txt, 'json'))
        except (json.JSONDecodeError, TypeError):
            raise ValueError(f'model neither called the tool nor returned JSON; reply: {txt[:200]!r}')

    def close(self):
        "Nothing to release. The HTTP client is fastllm's, and cached across chats."
        pass

